import numpy as np
W1 = W['W1']

def vec(r, c, ch):
    return W1[(r * 10 + c) * 5 + ch]

def corr(v1, v2):
    v1c = v1 - v1.mean()
    v2c = v2 - v2.mean()
    denom = np.linalg.norm(v1c) * np.linalg.norm(v2c)
    return np.dot(v1c, v2c) / denom if denom > 1e-9 else 0.0

for ch in [1, 4]:
    hcorrs = []
    vcorrs = []
    for r in range(2, 8):
        for c in range(1, 8):
            hcorrs.append(corr(vec(r, c, ch), vec(r, c + 1, ch)))
            if r < 7:
                vcorrs.append(corr(vec(r, c, ch), vec(r + 1, c, ch)))
    print(f"CH{ch}: H neighbor corr {np.mean(hcorrs):.3f}, V neighbor corr {np.mean(vcorrs):.3f}")

print("CH1 per-row horizontal neighbor corr:")
for r in range(2, 8):
