import numpy as np
W1 = W['W1']

def get_vec(r, c, ch):
    idx = (r*10 + c)*5 + ch
    return W1[idx]

def cos_sim(a, b):
    na = np.linalg.norm(a)
    nb = np.linalg.norm(b)
    if na < 1e-9 or nb < 1e-9:
        return np.nan
    return np.dot(a, b) / (na * nb)

# Control: reward channel row 1 (should be uniform across columns)
ch2_vecs = [get_vec(1, c, 2) for c in range(1,9)]
within_ch2 = [cos_sim(ch2_vecs[i], ch2_vecs[j]) for i in range(8) for j in range(i+1,8)]
print("CH2 row1 within-col cosine mean: %.3f" % np.nanmean(within_ch2))

rows = range(2,8)
cols = range(1,9)

# Channel 1 (moving objects)
ch1_vecs = {(r,c): get_vec(r,c,1) for r in rows for c in cols}
within_ch1 = []
between_ch1 = []
for r in rows:
    for c1 in cols:
        for c2 in cols:
            if c1 < c2:
                within_ch1.append(cos_sim(ch1_vecs[(r,c1)], ch1_vecs[(r,c2)]))
for r1 in rows:
    for r2 in rows:
        if r1 < r2:
            for c1 in cols:
                for c2 in cols:
                    between_ch1.append(cos_sim(ch1_vecs[(r1,c1)], ch1_vecs[(r2,c2)]))
print("CH1 within-row mean: %.3f, between-row mean: %.3f" % (np.nanmean(within_ch1), np.nanmean(between_ch1)))
print("CH1 per-row within-col mean:")
for r in rows:
    sims = [cos_sim(ch1_vecs[(r,c1)], ch1_vecs[(r,c2)]) for c1 in cols for c2 in cols if c1 < c2]
    print("  row %d: %.3f" % (r, np.nanmean(sims)))

